import SwiftUI

/// Version, data-source credits and the license notices that ship with the
/// app (MOBILE_LICENSES.txt, generated by packaging/third-party-licenses.py).
struct AboutView: View {
    let theme: ReckonTheme

    private var version: String {
        Bundle.main.object(forInfoDictionaryKey: "CFBundleShortVersionString") as? String ?? ""
    }

    private var licenses: String {
        guard let url = Bundle.main.url(forResource: "MOBILE_LICENSES", withExtension: "txt"),
              let text = try? String(contentsOf: url, encoding: .utf8)
        else { return "Reckon is released under the MIT License." }
        return text
    }

    var body: some View {
        ScrollView {
            VStack(alignment: .leading, spacing: 18) {
                VStack(alignment: .leading, spacing: 4) {
                    Text("Reckon \(version)")
                        .font(.title3.weight(.semibold))
                        .foregroundStyle(theme.swiftUI("text"))
                    Text("A natural-language calculator. Open source under the MIT License.")
                        .font(.subheadline)
                        .foregroundStyle(theme.swiftUI("muted"))
                }
                VStack(alignment: .leading, spacing: 8) {
                    Text("DATA")
                        .font(.caption.weight(.semibold))
                        .foregroundStyle(theme.swiftUI("muted"))
                    Link("Rates By Exchange Rate API", destination: URL(string: "https://www.exchangerate-api.com")!)
                    Link("Crypto prices powered by CoinGecko", destination: URL(string: "https://www.coingecko.com")!)
                }
                .font(.subheadline)
                .tint(theme.swiftUI("result"))
                VStack(alignment: .leading, spacing: 8) {
                    Text("LICENSES")
                        .font(.caption.weight(.semibold))
                        .foregroundStyle(theme.swiftUI("muted"))
                    Text(licenses)
                        .font(.caption.monospaced())
                        .foregroundStyle(theme.swiftUI("text"))
                        .textSelection(.enabled)
                }
            }
            .frame(maxWidth: .infinity, alignment: .leading)
            .padding(18)
        }
        .background(theme.swiftUI("surface"))
        .navigationTitle("About")
        .navigationBarTitleDisplayMode(.inline)
    }
}
